def longestApproxCommonSubstring(s, t, k):
    m, n = len(s), len(t)
    best = 0
    for d in range(-(m - 1), n):
        i0 = 0 if d >= 0 else -d
        j0 = i0 + d
        length = min(m - i0, n - j0)
        lo = 0
        bad = 0
        for hi in range(length):
            if s[i0 + hi] != t[j0 + hi]:
                bad += 1
                while bad > k:
                    if s[i0 + lo] != t[j0 + lo]:
                        bad -= 1
                    lo += 1
            if hi - lo + 1 > best:
                best = hi - lo + 1
    return best
